-- make_alias_ref: relation types and encyclopedic citations (additive, reversible)
alter table public.make_alias_ref
  add column if not exists relation_type text not null default 'same_make',
  add column if not exists source_citation_url text,
  add column if not exists source_citation_title text;
alter table public.make_alias_ref drop constraint if exists make_alias_ref_relation_type_check;
alter table public.make_alias_ref add constraint make_alias_ref_relation_type_check
  check (relation_type in ('same_make','successor_brand','tuner_or_builder','replica'));
alter table public.make_alias_ref drop constraint if exists make_alias_ref_kind_check;
alter table public.make_alias_ref add constraint make_alias_ref_kind_check
  check (kind in ('alias','case_punct','truncated_make','misspelled_make','coachbuilder_as_make','model_as_make','brand_relation'));
comment on column public.make_alias_ref.relation_type is
  'same_make: alias_text IS canonical_make for identity. successor_brand: same manufacturer lineage, identity-compatible but a distinct badge for category/comps. tuner_or_builder / replica: NOT the same make for identity; do not canonicalize.';
insert into public.make_alias_ref (alias_text,canonical_make,kind,relation_type,evidence_count,citation_vehicle_id,citation_url,source_citation_url,source_citation_title,rule,run_id)
select x.alias_text,x.canonical_make,x.kind,x.relation_type,x.evidence_count,x.citation_vehicle_id,x.source_citation_url,x.source_citation_url,x.source_citation_title,'make_relation_v1','make_relation_v1_20261026'
